window.docContents[117].resolve({"/rules/RG1006/#RG1006-limitations":{"contents":"The helper exception is conservative: elaborators defined in the audited module, run_tac or by_elab in the recursion's proofs make the checker reject a definition Lean accepts.\n\nEditor feedback may be pending until the project command completes the fresh-frontend check.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1006: Unsafe and partial declarations require exact helper authentication","header":"Limitations and unsupported cases","id":"/rules/RG1006/#RG1006-limitations"},"/rules/RG2005/#RG2005-limitations":{"contents":"This page's example is a diagnostic demonstration: the violating run is INCOMPLETE by design and is not accepted negative evidence. Its corrected counterpart passed a completed positive check.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2005: Required admission and source evidence must be complete","header":"Limitations and unsupported cases","id":"/rules/RG2005/#RG2005-limitations"},"/rules/RG4003/#RG4003-limitations":{"contents":"Regula policy rejections of documentation examples can follow successful elaboration; this rule concerns compiler rejection patterns of lean-fail fences.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4003: Negative examples require completed intended rejection","header":"Limitations and unsupported cases","id":"/rules/RG4003/#RG4003-limitations"},"/rules/RG5002/#RG5002-limitations":{"contents":"Lean's broader linter.missingDocs checks all public declarations; this rule deliberately covers only registered material evidence.\n\nThe editor reports this rule only when the module has finished elaborating without errors; a module with elaboration errors gets RG2005 (incomplete) instead.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5002: Registered public material declarations require docstrings","header":"Limitations and unsupported cases","id":"/rules/RG5002/#RG5002-limitations"}});